DROP TABLE IF EXISTS `prospects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `prospects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_name` varchar(255) NOT NULL,
  `industry` varchar(150) DEFAULT NULL,
  `region` varchar(150) DEFAULT NULL,
  `company_size` varchar(50) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `contact_name` varchar(150) DEFAULT NULL,
  `contact_email` varchar(150) DEFAULT NULL,
  `contact_phone` varchar(50) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `segment` varchar(100) DEFAULT NULL,
  `score` int(11) DEFAULT 0,
  `score_reason` text DEFAULT NULL,
  `status` enum('new','qualified','contacted','converted','rejected') DEFAULT 'new',
  `raw_data_id` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `organization_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `raw_data_id` (`raw_data_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_prospects_org_id` (`organization_id`),
  CONSTRAINT `fk_prospects_org_id` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `prospects_ibfk_1` FOREIGN KEY (`raw_data_id`) REFERENCES `raw_data` (`id`),
  CONSTRAINT `prospects_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35711 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

